+                Asserts.assertEquals(
+                        RequestStackTraceHelper.JVMTI_ERROR_WRONG_PHASE, rc,
+                        "expected WRONG_PHASE for excluded thread, got " + rc);
+            } finally {
+                JVM.include(Thread.currentThread());
+            }
+
+            r.stop();
+        }
+    }
+}

